const express = require('express');
const app = express();

// Resolve the application version: prefer the value injected by npm at
// runtime, then fall back to the "version" field in package.json, then
// fall back to 'unknown' if neither is available.
function getVersion() {
  if (process.env.npm_package_version) {
    return process.env.npm_package_version;
  }
  try {
    return require('./package.json').version;
  } catch {
    return 'unknown';
  }
}

// Names of environment variables that must be present for the application
// to operate correctly.  Only the names are stored here; values are never
// read, logged, or included in any response.
const REQUIRED_ENV_VARS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: getVersion(),
    uptime: process.uptime(),   // seconds since the process started
  });
});

// /ready returns 200 only when every required environment variable is set
// and non-empty.  On failure it returns 503 and lists the *names* of
// whichever variables are missing so the problem is easy to diagnose.
app.get('/ready', (req, res) => {
  const missing = REQUIRED_ENV_VARS.filter(
    (name) => !process.env[name]
  );

  if (missing.length === 0) {
    return res.json({ ready: true });
  }

  return res.status(503).json({
    ready: false,
    missing,  // variable names only — values are never exposed
  });
});

